import { MessageRole as PromptlMessageRole } from '$promptl/types'

export enum MessageRole {
  user = PromptlMessageRole.user,
  assistant = PromptlMessageRole.assistant,
}

export enum ContentType {
  text = 'text',
  image = 'image',
  tool_use = 'tool_use',
