        parser.error(
          PARSER_ERRORS.unclosedAttributeValue(quoteMark || CUSTOM_TAG_END),
        )
      }
    }
    throw error
  }
  if (value.length === 0 && !quoteMark) {
    parser.error(PARSER_ERRORS.missingAttributeValue)
