  node,
  scope,
  addStrayText,
  resolveExpression,
}: CompileNodeContext<MustacheTag>) {
  const expression = node.expression
  const value = await resolveExpression(expression, scope)
  if (value === undefined) return

  if (typeof value === 'object' && value !== null) {
