import { CUSTOM_CONTENT_TYPE_ATTR, TAG_NAMES } from '$promptl/constants'
import errors from '$promptl/error/errors'
import { ContentTag } from '$promptl/parser/interfaces'
import { ContentType, ContentTypeTagName } from '$promptl/types'

import { CompileNodeContext } from '../../types'

export async function compile(
  {
    node,
    scope,
    isInsideStepTag,
    isInsideMessageTag,
    isInsideContentTag,
    fullPath,
    resolveBaseNode,
    baseNodeError,
    popStrayText,
    addContent,
  }: CompileNodeContext<ContentTag>,
  attributes: Record<string, unknown>,
) {
  if (isInsideContentTag) {
    baseNodeError(errors.contentTagInsideContent, node)
  }

  for await (const childNode of node.children ?? []) {
    await resolveBaseNode({
      node: childNode,
      scope,
      isInsideStepTag,
      isInsideMessageTag,
      isInsideContentTag: true,
      fullPath,
    })
  }

  let type: ContentType
  if (node.name === TAG_NAMES.content) {
    if (attributes[CUSTOM_CONTENT_TYPE_ATTR] === undefined) {
      baseNodeError(errors.messageTagWithoutRole, node)
    }
    type = attributes[CUSTOM_CONTENT_TYPE_ATTR] as ContentType
    delete attributes[CUSTOM_CONTENT_TYPE_ATTR]
  } else {
    const contentTypeKeysFromTagName = Object.fromEntries(
      Object.entries(ContentTypeTagName).map(([k, v]) => [v, k]),
    )
    type =
      ContentType[
        contentTypeKeysFromTagName[node.name] as keyof typeof ContentType
      ]
  }

  const stray = popStrayText()

  if (type === ContentType.text && stray.text.length > 0) {
    addContent({
      node,
      content: {
        ...attributes,
        type: ContentType.text,
        text: stray.text,
        _promptlSourceMap: stray.sourceMap,
      },
    })
    return
  }

  if (type === ContentType.image && stray.text.length > 0) {
    addContent({
      node,
      content: {
        ...attributes,
        type: ContentType.image,
        image: stray.text,
        _promptlSourceMap: stray.sourceMap,
      },
    })
    return
  }

  if (type === ContentType.file && stray.text.length > 0) {
    const { mime: mimeType, ...rest } = attributes
    if (!mimeType) baseNodeError(errors.fileTagWithoutMimeType, node)

    addContent({
      node,
      content: {
        ...rest,
        type: ContentType.file,
        file: stray.text,
        mimeType: String(mimeType),
        _promptlSourceMap: stray.sourceMap,
      },
    })
    return
  }

  if (type == ContentType.toolCall) {
    const { id, name, ...rest } = attributes
    if (!id) baseNodeError(errors.toolCallTagWithoutId, node)
    if (!name) baseNodeError(errors.toolCallWithoutName, node)

    let toolArguments = rest['arguments']
    delete rest['arguments']
    if (toolArguments && typeof toolArguments === 'string') {
      try {
        rest['arguments'] = JSON.parse(toolArguments)
      } catch (e) {
        baseNodeError(errors.invalidToolCallArguments, node)
      }
    }

    addContent({
      node,
      content: {
        ...rest,
        type: ContentType.toolCall,
        toolCallId: String(id),
        toolName: String(name),
        toolArguments: (toolArguments ?? {}) as Record<string, unknown>,
      },
    })
    return
  }

  baseNodeError(errors.invalidContentType(type), node)
}
import { CUSTOM_MESSAGE_ROLE_ATTR, TAG_NAMES } from '$promptl/constants'
import errors from '$promptl/error/errors'
import { MessageTag, TemplateNode } from '$promptl/parser/interfaces'
import {
  ContentType,
  Message,
  MessageContent,
  MessageRole,
} from '$promptl/types'

import { CompileNodeContext } from '../../types'

export async function compile(
  props: CompileNodeContext<MessageTag>,
  attributes: Record<string, unknown>,
) {
  const {
    node,
    scope,
    isInsideStepTag,
    isInsideMessageTag,
    isInsideContentTag,
    fullPath,
    resolveBaseNode,
    baseNodeError,
    groupContent,
    groupStrayText,
    popContent,
    addMessage,
  } = props

  if (isInsideContentTag || isInsideMessageTag) {
    baseNodeError(errors.messageTagInsideMessage, node)
  }

  groupContent()

  let role = node.name as MessageRole
  if (node.name === TAG_NAMES.message) {
    if (attributes[CUSTOM_MESSAGE_ROLE_ATTR] === undefined) {
      baseNodeError(errors.messageTagWithoutRole, node)
    }
    role = attributes[CUSTOM_MESSAGE_ROLE_ATTR] as MessageRole
    delete attributes[CUSTOM_MESSAGE_ROLE_ATTR]
  }

  for await (const childNode of node.children ?? []) {
    await resolveBaseNode({
      node: childNode,
      scope,
      isInsideStepTag,
      isInsideMessageTag: true,
      isInsideContentTag,
      fullPath,
    })
  }

  groupStrayText()
  const content = popContent()

  const message = buildMessage(props as CompileNodeContext<MessageTag>, {
    role,
    attributes,
    content,
  })!
  addMessage(message)
}

type BuildProps<R extends MessageRole> = {
  role: R
  attributes: Record<string, unknown>
  content: { node?: TemplateNode; content: MessageContent }[]
}

function buildMessage<R extends MessageRole>(
  { node, baseNodeError }: CompileNodeContext<MessageTag>,
  { role, attributes, content }: BuildProps<R>,
): Message | undefined {
  if (!Object.values(MessageRole).includes(role)) {
    baseNodeError(errors.invalidMessageRole(role), node)
  }

  if (role !== MessageRole.assistant) {
    content.forEach((item) => {
      if (item.content.type === ContentType.toolCall) {
        baseNodeError(errors.invalidToolCallPlacement, item.node ?? node)
      }
    })
  }

  const message = {
    ...attributes,
    role,
    content: content.map((item) => item.content),
  } as Message

  if (role === MessageRole.user) {
    message.name = attributes.name ? String(attributes.name) : undefined
  }

  if (role === MessageRole.tool) {
    if (attributes.id === undefined) {
      baseNodeError(errors.toolMessageWithoutId, node)
    }

    message.toolId = String(attributes.id)
    delete message['id']
  }

  return message
}
export type ScopePointers = { [key: string]: number }
export type ScopeStash = unknown[]

export default class Scope {
  /**
   * Global stash
   * All variable values are stored in a single global array. This is done to allow multiple
   * scopes to share the same variable values and be able to modify them.
   *
   * For example:
   * ```md
   * {var1 = 1}
   * {#if <condition>}
   *  {var1 = 2}
   *  {var2 = 3}
   * {/if}
   * ```
   * In this case, there are two scopes: root and if. Both scopes share the same variable `var1`,
   * and modifying it in the if scope should also modify it in the root scope. But `var2` is only
   * defined in the if scope and should not be accessible in the root scope.
   *
   * Local pointers
   * Every scope has its own local pointers that contains the indexes of the variables in the global stash.
   */
  private globalStash: ScopeStash = [] // Stash of every variable value in the global scope
  private localPointers: ScopePointers = {} // Index of every variable in the stash in the current scope

  constructor(initialState: Record<string, unknown> = {}) {
    for (const [key, value] of Object.entries(initialState)) {
      this.localPointers[key] = this.addToStash(value)
    }
  }

  static withStash(stash: ScopeStash): Scope {
    const scope = new Scope()
    scope.globalStash = stash
    return scope
  }

  private readFromStash(index: number): unknown {
    return this.globalStash[index]
  }

  private addToStash(value: unknown): number {
    this.globalStash.push(value)
    return this.globalStash.length - 1
  }

  private modifyStash(index: number, value: unknown): void {
    this.globalStash[index] = value
  }

  exists(name: string): boolean {
    return name in this.localPointers
  }

  get(name: string): unknown {
    const index = this.localPointers[name] ?? undefined
    if (index === undefined)
      throw new Error(`Variable '${name}' does not exist`)
    return this.readFromStash(index)
  }

  set(name: string, value: unknown): void {
    if (!this.exists(name)) {
      this.localPointers[name] = this.addToStash(value)
      return
    }
    const index = this.localPointers[name]!
    this.modifyStash(index, value)
  }

  copy(localPointers?: ScopePointers): Scope {
    const scope = new Scope()
    scope.globalStash = this.globalStash
    scope.localPointers = { ...(localPointers ?? this.localPointers) }
    return scope
  }

  getStash(): ScopeStash {
    return this.globalStash
  }

  getPointers(): ScopePointers {
    return this.localPointers
  }

  setPointers(pointers: ScopePointers): void {
    this.localPointers = pointers
  }
}

export type ScopeContext = {
  onlyPredefinedVariables?: Set<string> // If defined, all usedUndefinedVariables that are not in this set will return an error
  usedUndefinedVariables: Set<string> // Variables that are not in current scope but have been used
  definedVariables: Set<string> // Variables that are in current scope
}
import Scope from '$promptl/compiler/scope'
import errors from '$promptl/error/errors'
import parse from '$promptl/parser'
import { Fragment, ReferenceTag } from '$promptl/parser/interfaces'

import { CompileNodeContext, TemplateNodeWithStatus } from '../../types'

type ForNodeWithStatus = TemplateNodeWithStatus & {
  status: TemplateNodeWithStatus['status'] & {
    refAst: Fragment
    refFullPath: string
  }
}

export async function compile(
  props: CompileNodeContext<ReferenceTag>,
  attributes: Record<string, unknown>,
) {
  const {
    node,
    scope,
    fullPath,
    referencePromptFn,
    baseNodeError,
    resolveBaseNode,
  } = props

  const nodeWithStatus = node as ForNodeWithStatus
  nodeWithStatus.status = {
    ...nodeWithStatus.status,
    scopePointers: scope.getPointers(),
  }

  const { path, ...refParameters } = attributes
  if (!path) baseNodeError(errors.referenceTagWithoutPrompt, node)
  if (typeof path !== 'string') baseNodeError(errors.invalidReferencePath, node)

  if (!nodeWithStatus.status.refAst || !nodeWithStatus.status.refFullPath) {
    if (!referencePromptFn) baseNodeError(errors.missingReferenceFunction, node)

    const prompt = await referencePromptFn!(path as string, fullPath)
    if (!prompt) baseNodeError(errors.referenceNotFound, node)
    const ast = parse(prompt!.content)
    nodeWithStatus.status.refAst = ast
    nodeWithStatus.status.refFullPath = prompt!.path
  }

  const refScope = new Scope(refParameters)
  await resolveBaseNode({
    ...props,
    node: nodeWithStatus.status.refAst,
    scope: refScope,
    fullPath: nodeWithStatus.status.refFullPath,
  })
}
import { tagAttributeIsLiteral } from '$promptl/compiler/utils'
import errors from '$promptl/error/errors'
import { ChainStepTag } from '$promptl/parser/interfaces'
import { Config, ContentType } from '$promptl/types'

import { CompileNodeContext } from '../../types'

function isValidConfig(value: unknown): value is Config | undefined {
  if (value === undefined) return true
  if (Array.isArray(value)) return false
  return typeof value === 'object'
}

export async function compile(
  {
    node,
    scope,
    isInsideStepTag,
    isInsideMessageTag,
    isInsideContentTag,
    fullPath,
    popStepResponse,
    groupContent,
    resolveBaseNode,
    baseNodeError,
    stop,
  }: CompileNodeContext<ChainStepTag>,
  attributes: Record<string, unknown>,
) {
  if (isInsideStepTag) {
    baseNodeError(errors.stepTagInsideStep, node)
  }

  const stepResponse = popStepResponse()

  const { as: responseVarName, raw: messageVarName, ...config } = attributes

  // The step must be processed.
  if (stepResponse === undefined) {
    if (!isValidConfig(config)) {
      baseNodeError(errors.invalidStepConfig, node)
    }

    for await (const childNode of node.children ?? []) {
      await resolveBaseNode({
        node: childNode,
        scope,
        isInsideStepTag: true,
        isInsideMessageTag,
        isInsideContentTag,
        fullPath,
      })
    }

    // Stop the compiling process up to this point.
    stop(config as Config)
  }

  // The step has already been process, this is the continuation of the chain.

  if ('raw' in attributes) {
    if (!tagAttributeIsLiteral(node, 'raw')) {
      baseNodeError(errors.invalidStaticAttribute('raw'), node)
    }

    scope.set(String(messageVarName), stepResponse)
  }

  if ('as' in attributes) {
    if (!tagAttributeIsLiteral(node, 'as')) {
      baseNodeError(errors.invalidStaticAttribute('as'), node)
    }

    const textResponse = (stepResponse?.content ?? []).filter(c => c.type === ContentType.text).map(c => c.text).join('')
    let responseVarValue = textResponse

    if ("schema" in config) {
      try {
        responseVarValue = JSON.parse(responseVarValue.trim())
      } catch (error) {
        baseNodeError(errors.functionCallError(error), node)
      }
    }

    scope.set(String(responseVarName), responseVarValue)
  }

  groupContent()
}
