export enum NodeType {
  Literal = 'Literal',
  Identifier = 'Identifier',
  ObjectExpression = 'ObjectExpression',
  ArrayExpression = 'ArrayExpression',
  SequenceExpression = 'SequenceExpression',
  LogicalExpression = 'LogicalExpression',
  BinaryExpression = 'BinaryExpression',
  UnaryExpression = 'UnaryExpression',
  AssignmentExpression = 'AssignmentExpression',
  UpdateExpression = 'UpdateExpression',
  MemberExpression = 'MemberExpression',
  ConditionalExpression = 'ConditionalExpression',
  CallExpression = 'CallExpression',
  ChainExpression = 'ChainExpression',
}

type RaiseErrorFn<T = void | never> = (
  { code, message }: { code: string; message: string },
  node: Node,
) => T

export type ResolveNodeProps<N extends Node> = {
  node: N
  scope: Scope
  raiseError: RaiseErrorFn<never>
}

export type UpdateScopeContextProps<N extends Node> = {
  node: N
  scopeContext: ScopeContext
  raiseError: RaiseErrorFn<void>
}
import {
  resolveLogicNode,
  updateScopeContextForNode,
} from '$promptl/compiler/logic'
import type {
  ResolveNodeProps,
  UpdateScopeContextProps,
} from '$promptl/compiler/logic/types'
import { isIterable } from '$promptl/compiler/utils'
import errors from '$promptl/error/errors'
import type { ArrayExpression } from 'estree'

/**
 * ### ArrayExpression
 * Returns an array of values
 */

export async function resolve({
  node,
  ...props
}: ResolveNodeProps<ArrayExpression>) {
  const { raiseError } = props
  const resolvedArray = []
  for (const element of node.elements) {
    if (!element) continue
    if (element.type !== 'SpreadElement') {
      const value = await resolveLogicNode({
        node: element,
        ...props,
      })
      resolvedArray.push(value)
      continue
    }

    const spreadObject = await resolveLogicNode({
      node: element.argument,
      ...props,
    })

    if (!isIterable(spreadObject)) {
      raiseError(errors.invalidSpreadInArray(typeof spreadObject), element)
    }

    for await (const value of spreadObject as Iterable<unknown>) {
      resolvedArray.push(value)
    }
  }

  return resolvedArray
}

export function updateScopeContext({
  node,
  ...props
}: UpdateScopeContextProps<ArrayExpression>) {
  for (const element of node.elements) {
    if (!element) continue

    updateScopeContextForNode({
      node: element.type === 'SpreadElement' ? element.argument : element,
      ...props,
    })
  }
}
// https://github.com/estree/estree/blob/master/es5.md#binary-operations
export const BINARY_OPERATOR_METHODS: {
  [operator: string]: (left: any, right: any) => unknown
} = {
  // BinaryExpression
  '==': (left, right) => left == right,
  '!=': (left, right) => left != right,
  '===': (left, right) => left === right,
  '!==': (left, right) => left !== right,
  '<': (left, right) => left < right,
  '<=': (left, right) => left <= right,
  '>': (left, right) => left > right,
  '>=': (left, right) => left >= right,
  '<<': (left, right) => left << right,
  '>>': (left, right) => left >> right,
  '>>>': (left, right) => left >>> right,
  '+': (left, right) => left + right,
  '-': (left, right) => left - right,
  '*': (left, right) => left * right,
  '/': (left, right) => left / right,
  '%': (left, right) => left % right,
  '|': (left, right) => left | right,
  '^': (left, right) => left ^ right,
  '&': (left, right) => left & right,
  in: (left, right) => left in right,
  instanceof: (left, right) => (left as object) instanceof right,

  // LogicalExpression
  '||': (left, right) => left || right,
  '&&': (left, right) => left && right,
  '??': (left, right) => left ?? right,
}

// https://github.com/estree/estree/blob/master/es5.md#unary-operations
export const UNARY_OPERATOR_METHODS: {
  [operator: string]: (value: any, prefix: any) => unknown
} = {
  // UnaryExpression
  '-': (value, prefix) => (prefix ? -value : value),
  '+': (value, prefix) => (prefix ? +value : value),
  '!': (value, _) => !value,
  '~': (value, _) => ~value,
  typeof: (value, _) => typeof value,
  void: (value, _) => void value,
}

// https://github.com/estree/estree/blob/master/es5.md#memberexpression
export const MEMBER_EXPRESSION_METHOD = (
  object: any,
  property: any,
): unknown => {
  const value = object[property]
  return typeof value === 'function' ? value.bind(object) : value
}

// https://github.com/estree/estree/blob/master/es5.md#assignmentexpression
export const ASSIGNMENT_OPERATOR_METHODS: {
  [operator: string]: (left: any, right: any) => unknown
} = {
  '=': (_, right) => right,
  '+=': (left, right) => left + right,
  '-=': (left, right) => left - right,
  '*=': (left, right) => left * right,
  '/=': (left, right) => left / right,
  '%=': (left, right) => left % right,
  '<<=': (left, right) => left << right,
  '>>=': (left, right) => left >> right,
  '>>>=': (left, right) => left >>> right,
  '|=': (left, right) => left | right,
  '^=': (left, right) => left ^ right,
  '&=': (left, right) => left & right,
}
