/**
 * ### BinaryExpression
 * Represents a simple operation between two operands.
 *
 * Example: `{a > b}`
 */
export async function resolve({
  node,
  raiseError,
  ...props
}: ResolveNodeProps<BinaryExpression | LogicalExpression>) {
  const binaryOperator = node.operator
  if (!(binaryOperator in BINARY_OPERATOR_METHODS)) {
    raiseError(errors.unsupportedOperator(binaryOperator), node)
  }
  const leftOperand = await resolveLogicNode({
    node: node.left,
    raiseError,
    ...props,
  })
  const rightOperand = await resolveLogicNode({
    node: node.right,
    raiseError,
    ...props,
  })

  return BINARY_OPERATOR_METHODS[binaryOperator]?.(leftOperand, rightOperand)
}

export function updateScopeContext({
  node,
  ...props
}: UpdateScopeContextProps<BinaryExpression | LogicalExpression>) {
  const binaryOperator = node.operator
  if (!(binaryOperator in BINARY_OPERATOR_METHODS)) {
    props.raiseError(errors.unsupportedOperator(binaryOperator), node)
  }

  updateScopeContextForNode({ node: node.left, ...props })
  updateScopeContextForNode({ node: node.right, ...props })
}
import type {
  ResolveNodeProps,
  UpdateScopeContextProps,
} from '$promptl/compiler/logic/types'
import CompileError from '$promptl/error/error'
import errors from '$promptl/error/errors'
import type { SimpleCallExpression } from 'estree'

import { resolveLogicNode, updateScopeContextForNode } from '..'

/**
 * ### CallExpression
 * Represents a method call.
 *
 * Examples: `foo()` `foo.bar()`
 */
export async function resolve(props: ResolveNodeProps<SimpleCallExpression>) {
  const { node, raiseError } = props
  const method = (await resolveLogicNode({
    ...props,
    node: node.callee,
  })) as Function

  if (typeof method !== 'function') {
    raiseError(errors.notAFunction(typeof method), node)
  }

  const args = await resolveArgs(props)
  return await runMethod({ ...props, method, args })
}

function resolveArgs(
  props: ResolveNodeProps<SimpleCallExpression>,
): Promise<unknown[]> {
  const { node } = props
  return Promise.all(
    node.arguments.map((arg) =>
      resolveLogicNode({
        ...props,
        node: arg,
      }),
    ),
  )
}

async function runMethod({
  method,
  args,
  node,
  raiseError,
}: ResolveNodeProps<SimpleCallExpression> & {
  method: Function
  args: unknown[]
}) {
  try {
    return await method(...args)
  } catch (error: unknown) {
    if (error instanceof CompileError) throw error
    raiseError(errors.functionCallError(error), node)
  }
}

export function updateScopeContext({
  node,
  ...props
}: UpdateScopeContextProps<SimpleCallExpression>) {
  updateScopeContextForNode({ node: node.callee, ...props })
  for (const arg of node.arguments) {
    updateScopeContextForNode({ node: arg, ...props })
  }
}
